mapper.select:
SELECT id, username, password, real_name, age, email, phone, status, role, create_at
FROM sys_user
WHERE username = #{username}

SELECT id, username, password, real_name, age, email, phone, status, role, create_at
FROM sys_user
WHERE id = #{id}

SELECT id, username, password, real_name, age, email, phone, status, role, create_at
FROM sys_user


        AND username LIKE CONCAT('%', #{username}, '%')


        AND role = #{role}


        AND status = #{enabled}


ORDER BY id
